#import <Cocoa/Cocoa.h>
#import "../Sources/AMPreflight.h"
#import "AcceptanceFixtures.h"
static NSUInteger checks;
static void Check(BOOL ok,NSString *message){checks++;if(!ok){fprintf(stderr,"FAIL: %s\n",message.UTF8String);exit(1);}}
static NSDictionary *Validate(NSArray *items,NSString *teacher){NSDictionary *context=@{@"format":@"am-preflight-context-v1",@"batchID":@"synthetic",@"reportVersion":@"v1",@"requirements":teacher,@"documents":@[],@"images":@[]};NSDictionary *result=@{@"format":@"am-preflight-results-v1",@"batchID":@"synthetic",@"reportVersion":@"v1",@"semanticRequirements":items,@"findings":@[],@"checked":@[],@"unverified":@[],@"requirementChecks":@[]};return AMPreflightValidateResult(result,context,NULL);}
int main(){@autoreleasepool{
    NSError *fixtureError=nil;Check(!AMAcceptanceCases(nil,12,&fixtureError) && fixtureError!=nil,@"missing bundle fixture is an error without parsing nil data");Check(AMAcceptanceCases([NSURL fileURLWithPath:@"Tests/Fixtures/semantic-requirements-gold.json"],12,NULL).count==12,@"acceptance resource loader validates real corpus");Check(!AMAcceptanceCases([NSURL fileURLWithPath:@"Tests/Fixtures/semantic-requirements-gold.json"],4,NULL),@"wrong corpus shape cannot become a successful run");
    NSString *teacher=@"框架已经处理输入循环。\n完成排序算法，并说明复杂度。\n熟练题目可跳过，但需标明并补充探索。";
    NSDictionary *task=@{@"text":@"实现排序并分析复杂度",@"condition":@"",@"line":@2,@"quote":@"完成排序算法，并说明复杂度。"};
    NSDictionary *result=Validate(@[task],teacher);NSArray *items=result[@"semanticRequirements"];Check(items.count==1,@"paraphrase accepted through teacher evidence");Check(![items[0][@"id"] isEqual:@""],@"canonical identity generated locally");Check([items[0][@"id"] isEqual:Validate(@[task],teacher)[@"semanticRequirements"][0][@"id"]],@"same source and label have stable identity");
    NSMutableDictionary *wrong=task.mutableCopy;wrong[@"quote"]=@"invented requirement";Check([Validate(@[wrong],teacher)[@"semanticRequirements"] count]==0,@"invented teacher citation rejected");wrong=task.mutableCopy;wrong[@"line"]=@1;Check([Validate(@[wrong],teacher)[@"semanticRequirements"] count]==0,@"wrong source position rejected");wrong=task.mutableCopy;wrong[@"line"]=@YES;Check([Validate(@[wrong],teacher)[@"semanticRequirements"] count]==0,@"boolean cannot be a source line");
    Check([Validate(@[task,task],teacher)[@"semanticRequirements"] count]==1,@"duplicate generated items are deduplicated");
    NSDictionary *answer=@{@"path":@"answer.md",@"text":@"排序复杂度为O(n log n)。",@"version":@"synthetic"};NSDictionary *context=@{@"format":@"am-preflight-context-v1",@"batchID":@"synthetic",@"reportVersion":@"v1",@"requirements":teacher,@"verifiedTextRequirements":@[teacher],@"documents":@[answer],@"images":@[]};NSDictionary *review=@{@"format":@"am-preflight-results-v1",@"batchID":@"synthetic",@"reportVersion":@"v1",@"semanticRequirements":@[task],@"findings":@[],@"checked":@[],@"unverified":@[],@"requirementChecks":@[@{@"requirement":task[@"text"],@"status":@"checked",@"reason":@"引用支持复杂度说明",@"path":answer[@"path"],@"version":answer[@"version"],@"line":@1,@"evidence":answer[@"text"]}]};Check([AMPreflightValidateResult(review,context,NULL)[@"requirementChecks"][0][@"status"] isEqual:@"checked"],@"paraphrased requirement can be checked through verified teacher quote and answer evidence");
    NSDictionary *recognized=AMValidateRecognizedFields(teacher,@{@"requirements":@[task]});Check([recognized[@"requirements"][0][@"text"] isEqual:task[@"text"]],@"Luna field proposals retain paraphrases with validated source evidence");
    NSDictionary *condition=@{@"text":@"满足补充探索条件后可跳题",@"condition":@"标明跳题并补充探索",@"line":@3,@"quote":@"熟练题目可跳过，但需标明并补充探索。"};Check([Validate(@[condition],teacher)[@"semanticRequirements"][0][@"condition"] isEqual:condition[@"condition"]],@"conditional requirement remains attached");
    NSArray *gold=[NSJSONSerialization JSONObjectWithData:[NSData dataWithContentsOfFile:@"Tests/Fixtures/semantic-requirements-gold.json"] options:0 error:NULL],*held=[NSJSONSerialization JSONObjectWithData:[NSData dataWithContentsOfFile:@"Tests/Fixtures/semantic-requirements-holdout.json"] options:0 error:NULL];Check(gold.count==12 && held.count==4,@"separate golden and held-out semantic quality corpus");
    printf("PASS: %lu semantic source validation assertions; model quality requires independent live review\n",(unsigned long)checks);
}}
